//
//  PhotoImportUITestSupport.swift
//  KataGo iOS
//
//  DEBUG-only test support for the end-to-end photo-import UI test.
//
//  XCUITest cannot drive the system PhotosPicker (it runs out-of-process), so
//  this hook feeds a bundled, wide-margin clear-board image (img_00009, a
//  deterministic synthetic 9x9 board — never a marginal/real photo) straight
//  into the same path the "Photo Library…" completion drives: it sets
//  `TopUIState.pendingPhotoImport`, so `PhotoImportSheet` presents and runs the
//  real recognition → preview → Import flow. The image is embedded as base64 so
//  the whole thing — code AND data — is compiled out of Release (mirrors the
//  UITestSeed pattern). Fires once, only when the launch argument is present.
//

#if DEBUG
import Foundation
import KataGoUICore

enum PhotoImportUITestSupport {
    /// Pass in `XCUIApplication.launchArguments` to auto-present the photo-import
    /// sheet with the bundled test board on launch.
    static let launchArg = "--uitest-photo-import"

    /// Fixed name so the UI test can find the imported game in the library.
    static let importedGameName = "UITest Photo Board"

    /// True when the app was launched to drive the photo-import UI test.
    static var isActive: Bool {
        ProcessInfo.processInfo.arguments.contains(launchArg)
    }

    /// Idempotently presents the photo-import sheet with the bundled test board.
    /// No-op unless the launch argument is present and nothing is pending yet.
    @MainActor
    static func presentIfNeeded(into topUIState: TopUIState) {
        guard isActive else { return }
        guard topUIState.pendingPhotoImport == nil else { return }
        guard let data = Data(base64Encoded: boardImageBase64) else { return }
        topUIState.pendingPhotoImport = PendingPhotoImport(
            imageData: data,
            suggestedName: importedGameName
        )
    }

    /// img_00009.jpg (wide-margin synthetic 9x9 board) as base64, split into
    /// chunks joined at runtime to keep each string literal small.
    private static let boardImageBase64: String = [
        "",
        "",
        "",
        "",
        "",
        "",
        "",
        "",
        "",
        "",
        "",
        "",
        "",
        "",
        "",
        "",
        "",
        "",
        "",
        "",
        "",
        "",
        "",
        "",
        "",
    ].joined()
}
#endif
